class MethodTest {
    public void test() {
        enum LocalEnum { A, B }
        System.out.println(LocalEnum.A);
    }
}

enum Level { LOW, HIGH }
Level a = Level.LOW;
Level b = Level.LOW;
System.out.println(a == b);
System.out.println(a.equals(b));

enum Action {
    RUN {
        @Override public void perform() { System.out.print("Run "); }
    },
    STOP {
        @Override public void perform() { System.out.print("Stop"); }
    };
    public abstract void perform();
}
Action.RUN.perform();
Action.STOP.perform();

enum Color {
    RED;
    Color() {}
}
Color c = new Color();

enum Config {
    INSTANCE;
    public int value = 10;
}
Config.INSTANCE.value = 20;
Config c = Config.INSTANCE;
System.out.println(c.value);

enum Size {
    SMALL {
        @Override public String toString() { return "S"; }
    };
}
System.out.println(Size.SMALL.name() + ":" + Size.SMALL.toString());

enum Phase { SOLID, LIQUID }
Phase p = null;
switch (p) {
    case SOLID: System.out.println("Solid"); break;
    default: System.out.println("Default"); break;
}

enum Level { LOW, HIGH }
Level l = Level.LOW;
switch (l) {
    case Level.LOW: System.out.println("Low"); break;
    default: break;
}

interface Run {
    void execute();
}
enum Task implements Run {
    PRINT {
        public void execute() { System.out.print("Print"); }
    }
}
Task.PRINT.execute();

import java.lang.reflect.Constructor;
enum Service { INSTANCE; }
Constructor<Service> constructor = Service.class.getDeclaredConstructor(String.class, int.class);
constructor.setAccessible(true);
Service s = constructor.newInstance("TEST", 0);

enum Choice { YES, NO }
Choice[] v1 = Choice.values();
Choice[] v2 = Choice.values();
System.out.println(v1 == v2);
System.out.println(v1[0] == v2[0]);

enum Speed {
    FAST;
    public Speed() {}
}

import java.util.EnumMap;
enum TaskState { OPEN, CLOSED }
EnumMap<TaskState, String> map = new EnumMap<>(TaskState.class);
map.put(null, "Void");

enum Alert { GREEN, RED }
Alert a = Alert.RED;
switch (a) {
    case GREEN: System.out.println("Green"); break;
    default: System.out.println("Default Alert"); break;
}

enum Action {
    START {
        @Override public void execute() {}
    }
}
Action a = Action.START;
System.out.println(a.getClass().getName().contains("$"));

// Example template
